"def test_claim_users_with_mixed_identifiers(enterprise, enterprise_mocks):
    users = {
        'usrFakeUserId': 'managed',
        'someone@example.com': 'unmanaged',
        'anotheruser': 'managed'
    }
    result = enterprise.claim_users(users)

    assert isinstance(result, ManageUsersResponse)
    assert enterprise_mocks.claim_users.call_count == 1

    expected_payload = {
        'users': [
            {'id': 'usrFakeUserId', 'state': 'managed'},
            {'email': 'someone@example.com', 'state': 'unmanaged'},
            {'id': 'anotheruser', 'state': 'managed'}
        ]
    }
    assert enterprise_mocks.claim_users.last_request.json() == expected_payload

    assert enterprise_mocks.claim_users.last_request.url == f'{enterprise.url}/users/claim'"

"@pytest.mark.parametrize('django_redis_installed', (True, False))
def test_rediscache_django_redis_installed(django_redis_installed):
    with mock.patch('environ.compat.find_spec') as mock_find_spec:
        mock_find_spec.return_value = django_redis_installed
        driver = environ.compat.choose_rediscache_driver()

        if django_redis_installed:
            assert driver == 'django_redis.cache.RedisCache'
        else:
            assert driver != 'django_redis.cache.RedisCache'"

"@mock.patch('os.kill')
@mock.patch('os.getpid')
@mock.patch(builtin('open'), new_callable=mock.mock_open)
def test_validate_process_not_running(mock_open, mock_getpid, mock_kill):
    pidfile = gunicorn.pidfile.Pidfile('test.pid')
    mock_open.return_value.__enter__.return_value.read.return_value = '12345'
    mock_getpid.return_value = 54321
    mock_kill.side_effect = OSError(errno.ESRCH, "No such process")

    assert pidfile.validate() is None
    mock_kill.assert_called_once_with(12345, 0)"

"def test_convert_options_to_json_with_changes():
    options = {
        'fields': ['Name', 'Phone', 'Email'],
        'sort': ['Name', '-Age'],
        'use_field_ids': True,
        'view': 'Main View',
        'user_locale': 'en-US',
        'time_zone': 'America/New_York'
    }

    expected_json = {
        'fields': ['Email', 'Phone', 'Name'],
        'sort': [
            {'field': 'Name', 'direction': 'asc'},
            {'field': 'Age', 'direction': 'desc'}
        ],
        'returnFieldsByFieldId': True,
        'view': 'Main View'
    }

    expected_params = {
        'userLocale': 'en-US',
        'timeZone': 'America/New_York'
    }

    result_json, result_params = options_to_json_and_params(options)

    assert result_json == expected_json
    assert result_params == expected_params"
